use glam::DVec3;use ingetrazo_gui::{IngeTrazoApp,navigation::{self,Mode}};
fn frame(app:&mut IngeTrazoApp,ctx:&egui::Context,time:f64,events:Vec<egui::Event>){let _=ctx.run(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(time),focused:true,events,..Default::default()},|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(app,ui,rect,&response);});});}
fn button(p:egui::Pos2,pressed:bool)->egui::Event{egui::Event::PointerButton{pos:p,button:egui::PointerButton::Primary,pressed,modifiers:egui::Modifiers::NONE}}
fn main(){let mut rows=vec![];for name in ["look-move-release","look-press-move-release"]{let mut app=IngeTrazoApp::new();app.camera.distance=10.;app.camera.look_from(DVec3::new(0.,0.,1.68),DVec3::Y);app.activate_navigation(Mode::Look);let ctx=egui::Context::default();frame(&mut app,&ctx,0.,vec![]);let before=app.camera.eye();let a=egui::pos2(400.,300.);let b=egui::pos2(440.,260.);
let press=vec![egui::Event::PointerMoved(a),button(a,true)];let tail=vec![egui::Event::PointerMoved(b),button(b,false)];if name=="look-move-release"{frame(&mut app,&ctx,0.01,press);frame(&mut app,&ctx,0.02,tail);}else{frame(&mut app,&ctx,0.01,press.into_iter().chain(tail).collect());}
rows.push(serde_json::json!({"name":name,"eye":app.camera.eye().to_array(),"before_eye":before.to_array(),"yaw":app.camera.yaw,"pitch":app.camera.pitch,"undo":app.undo_stack.len()}));}println!("{}",serde_json::json!({"cases":rows}));}
